mapper.select:
SELECT 
  FROM emp24_joint_leave
       LEFT OUTER JOIN apr01_appr apr01 ON apr01.apr01_appr_id = emp24_appr_id
 WHERE emp24_joint_leave_id = #{jointLeaveId}
   AND emp24_company_id = #{companyId}

mapper.update:
UPDATE emp24_joint_leave
   SET emp24_start_date = #{startDate},
       emp24_close_date = #{closeDate},
       emp24_reason     = #{reason}
 WHERE emp24_joint_leave_id = #{jointLeaveId}
   AND emp24_company_id = #{companyId}

mapper.delete:
DELETE FROM emp24_joint_leave
 WHERE emp24_company_id = #{companyId}
   AND emp24_joint_leave_id IN
#{jointLeaveId}
